package my.webgso;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.List;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.ss.util.CellRangeAddress;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

/** A native Excel report generated by the application's existing Apache POI runtime. */
public final class ApiResultsExcel {
  public static final String CONTENT_TYPE =
      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

  private ApiResultsExcel() {}

  public static byte[] create(ApiRetestService.Job job) {
    var items = List.copyOf(job.items);
    try (var book = new XSSFWorkbook();
        var output = new ByteArrayOutputStream()) {
      var sheet = book.createSheet("API test results");
      sheet.setDisplayGridlines(false);
      var font = book.createFont();
      font.setFontName("Arial");
      font.setFontHeightInPoints((short) 10);
      var body = book.createCellStyle();
      body.setFont(font);
      body.setVerticalAlignment(VerticalAlignment.TOP);
      body.setWrapText(true);
      var headerFont = book.createFont();
      headerFont.setFontName("Arial");
      headerFont.setFontHeightInPoints((short) 10);
      headerFont.setBold(true);
      headerFont.setColor(IndexedColors.WHITE.getIndex());
      var header = book.createCellStyle();
      header.cloneStyleFrom(body);
      header.setFont(headerFont);
      header.setFillForegroundColor(IndexedColors.DARK_GREEN.getIndex());
      header.setFillPattern(FillPatternType.SOLID_FOREGROUND);
      var number = book.createCellStyle();
      number.cloneStyleFrom(body);
      number.setDataFormat(book.createDataFormat().getFormat("0"));
      number.setAlignment(HorizontalAlignment.RIGHT);
      var date = book.createCellStyle();
      date.cloneStyleFrom(body);
      date.setDataFormat(book.createDataFormat().getFormat("dd mmm yyyy hh:mm:ss"));
      var title = sheet.createRow(0);
      title.setHeightInPoints(30);
      text(title, 0, "GSO WEB SERVICES | API test results", header);
      sheet.addMergedRegion(new CellRangeAddress(0, 0, 0, 6));
      var identity = sheet.createRow(1);
      identity.setHeightInPoints(23);
      text(identity, 0, "Check ID", body);
      text(identity, 1, job.id, body);
      sheet.addMergedRegion(new CellRangeAddress(1, 1, 1, 6));
      var completed = sheet.createRow(2);
      completed.setHeightInPoints(23);
      text(completed, 0, "Completed at (MYT)", body);
      var when = completed.createCell(1);
      when.setCellStyle(date);
      if (job.finishedAt != null)
        when.setCellValue(job.finishedAt.atZoneSameInstant(Policies.LOCAL).toLocalDateTime());
      var summary = sheet.createRow(3);
      summary.setHeightInPoints(23);
      text(summary, 0, "APIs checked", body);
      text(summary, 2, "Success", body);
      text(summary, 4, "Failed", body);
      String[] names = {
        "Plant ID (system)",
        "Plant name",
        "API",
        "Result",
        "HTTP status",
        "Response time (ms)",
        "Message"
      };
      var headings = sheet.createRow(5);
      headings.setHeightInPoints(30);
      for (int column = 0; column < names.length; column++)
        text(headings, column, names[column], header);
      int rowIndex = 6;
      for (var item : items) {
        var row = sheet.createRow(rowIndex++);
        numeric(row, 0, item.plantId(), number);
        text(row, 1, item.plantName(), body);
        text(row, 2, item.dataset(), body);
        text(row, 3, item.status(), body);
        numeric(row, 4, item.httpStatus(), number);
        numeric(row, 5, item.responseMillis(), number);
        text(row, 6, item.message(), body);
        int lines = 1;
        for (String line : clean(item.message()).split("\\R", -1))
          lines += Math.max(1, (line.length() + 59) / 60);
        row.setHeightInPoints(Math.min(409, Math.max(30, lines * 14)));
      }
      int[] widths = {20, 30, 26, 14, 13, 22, 66};
      for (int column = 0; column < widths.length; column++)
        sheet.setColumnWidth(column, widths[column] * 256);
      sheet.createFreezePane(2, 6);
      sheet.setAutoFilter(new CellRangeAddress(5, Math.max(5, rowIndex - 1), 0, 6));
      for (int column : new int[] {1, 3, 5}) {
        var cell = summary.createCell(column);
        cell.setCellStyle(number);
        if (items.isEmpty()) cell.setCellValue(0);
        else
          cell.setCellFormula(
              column == 1
                  ? "COUNTA(A7:A" + rowIndex + ")"
                  : "COUNTIF(D7:D"
                      + rowIndex
                      + ",\""
                      + (column == 3 ? "Success" : "Failed")
                      + "\")");
      }
      if (!items.isEmpty()) {
        var formatting = sheet.getSheetConditionalFormatting();
        var failed = formatting.createConditionalFormattingRule("$D7=\"Failed\"");
        failed.createFontFormatting().setFontColorIndex(IndexedColors.DARK_RED.getIndex());
        var fill = failed.createPatternFormatting();
        fill.setFillBackgroundColor(IndexedColors.ROSE.getIndex());
        fill.setFillPattern(PatternFormatting.SOLID_FOREGROUND);
        formatting.addConditionalFormatting(
            new CellRangeAddress[] {new CellRangeAddress(6, rowIndex - 1, 3, 3)}, failed);
      }
      sheet.getPrintSetup().setLandscape(true);
      sheet.getPrintSetup().setPaperSize(PrintSetup.A4_PAPERSIZE);
      sheet.setFitToPage(true);
      sheet.getPrintSetup().setFitWidth((short) 1);
      sheet.getPrintSetup().setFitHeight((short) 0);
      sheet.setRepeatingRows(new CellRangeAddress(5, 5, -1, -1));
      book.getCreationHelper().createFormulaEvaluator().evaluateAll();
      book.write(output);
      return output.toByteArray();
    } catch (IOException e) {
      throw new IllegalStateException("Could not create API results Excel workbook.", e);
    }
  }

  private static void text(Row row, int column, String value, CellStyle style) {
    var cell = row.createCell(column, CellType.STRING);
    cell.setCellValue(clean(value));
    cell.setCellStyle(style);
  }

  private static void numeric(Row row, int column, Number value, CellStyle style) {
    var cell = row.createCell(column);
    if (value != null) cell.setCellValue(value.doubleValue());
    cell.setCellStyle(style);
  }

  private static String clean(String value) {
    if (value == null) return "";
    var text = value.replaceAll("[\\x00-\\x08\\x0B\\x0C\\x0E-\\x1F]", "");
    return text.length() > 32767 ? text.substring(0, 32740) + " [truncated]" : text;
  }
}
